 ]},
 {"clause_id": "c047", "issues": [
   {"issue": "\"Insubstantial\" is defined by the same circular test — a portion that \"would not impair or otherwise affect the intended use of the Property\" — with no threshold for \"affect,\" so a taking could satisfy neither definition or arguably both. The line between the substantial and insubstantial branches is unascertainable.", "type": 1, "prob": 0.26}
 ]},
 {"clause_id": "c048", "issues": [
